package dev.studyforge.banking.application; import dev.studyforge.banking.domain.*; import java.util.*; public final class WithdrawalService{private final UnitOfWork uow;private final TransactionFactory factory;private final FeeStrategy fee;private final List<NotificationPort> notifications;public WithdrawalService(UnitOfWork u,TransactionFactory f,FeeStrategy fee,List<NotificationPort> n){uow=u;factory=f;this.fee=fee;notifications=List.copyOf(n);}public Transaction withdraw(Withdrawal c){Money f=fee.calculate(c.amount());Transaction tx=factory.withdrawal(c.accountId(),c.amount(),f);Transaction done=uow.execute((a,t)->{Account old=a.findById(c.accountId()).orElseThrow(()->new AccountNotFoundException(c.accountId()));a.save(old.debit(c.amount().add(f)));t.save(tx);return tx;});for(NotificationPort n:notifications)try{n.transactionCompleted(done);}catch(RuntimeException e){throw new NotificationDeliveryException(done,e);}return done;}}
